</script>
<template><Teleport v-if="compact" to="#assistant-mobile-slot"><button class="assistant-trigger assistant-trigger--mobile" data-testid="assistant-toggle" :aria-expanded="open" aria-controls="global-assistant" @click="openPanel">提问</button></Teleport><button v-else class="assistant-trigger" data-testid="assistant-toggle" :aria-expanded="open" aria-controls="global-assistant" @click="openPanel">提问</button><aside v-show="open" id="global-assistant" class="assistant-panel assistant-workspace" data-testid="global-assistant" :style="{width:panelWidth+'px'}" :inert="!open" aria-label="全站研究助手" @keydown="trap"><div role="separator" tabindex="0" aria-orientation="vertical" :aria-valuenow="Math.round(panelWidth)" class="assistant-resizer" data-testid="assistant-resizer" aria-label="调整助手宽度（Alt 加方向键）" @pointerdown="resize($event,'panel')" @keydown="keyResize($event,'panel')"></div><section class="assistant-main" :class="{'has-messages':messages.length}"><header class="assistant-panel__header"><div class="assistant-heading"><strong>研究助手</strong><details ref="scopeDetails" class="assistant-scope-menu"><summary :class="{'scope-changed':scopeChanged}">{{scopeChanged?'范围已变化':'研究范围'}}</summary><div class="assistant-scope-popover"><strong>{{activeScope.label}}</strong><p class="meta">{{activeScope.snapshot}}</p><template v-if="scopeChanged"><p class="meta">页面范围已变化，之前的回答仍保留原范围。</p><p class="meta">新范围：{{pendingScope.snapshot}}</p><button @click="applyCurrentScope">采用此页面的新范围</button></template></div></details></div><button class="assistant-close quiet-button icon-button" title="收起研究助手" aria-label="收起研究助手" @click="close"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 18 6-6-6-6"/></svg></button></header><p v-if="storageState.failed" class="error" role="alert">浏览器存储不可用，当前会话仅保存在内存中；仍可导出。</p><div class="assistant-stage" :aria-hidden="!messages.length" :inert="!messages.length"><div ref="messageViewport" class="assistant-messages" tabindex="0" aria-label="会话内容" data-testid="conversation-messages" @scroll="onMessageScroll" @wheel.passive="releaseAnchor" @touchstart.passive="releaseAnchor" @pointerdown="releaseAnchor"><div ref="messageContent" class="assistant-message-content"><article v-for="m in messages" :key="m.id" :id="'message-'+m.id" class="conversation-turn" data-testid="conversation-turn" :class="m.role"><p class="meta turn-context"><strong class="turn-role" :data-role="m.role">{{ m.role==='user'?'你':'助手' }}</strong><span class="turn-mode" :data-mode="m.mode" :title="m.mode==='demo'?'前端模拟数据':'库内数据'">{{ m.mode==='demo'?'模拟':'库内' }}</span></p><p v-if="m.mode==='demo'&&m.role==='assistant'" class="demo">模拟流，仅用于演示。</p><MarkdownText class="answer-body" :text="displayText(m)" /><p v-if="m.status === 'cancelled' || m.status === 'interrupted'" class="meta">{{ m.status === 'cancelled' ? '已取消，未自动重试。' : '请求已中断，未自动重试。' }}</p><p v-if="m.metrics?.coverage === 'partial'" class="meta">覆盖不完整：答案仅基于部分匹配资料。</p><p v-if="m.attachment" class="meta">下一问依据：{{ m.attachment.title }}</p><details class="turn-details" data-testid="turn-details"><summary>详情</summary><p v-if="m.error" class="error"><strong>{{m.error.code}}</strong>：{{m.error.message}}</p><p class="meta">{{ m.scope }}</p><section v-if="m.plan" class="query-plan assistant-plan"><h2>检索范围</h2><p>业务日期：{{m.plan.business_date}} · 时区：{{m.plan.timezone}}</p><p>分类：{{m.plan.filters.category?(categoryName[m.plan.filters.category]||m.plan.filters.category):'全部分类'}} · 日期：{{m.plan.filters.date_from||'不限'}} 至 {{m.plan.filters.date_to||'不限'}}（起止日期均包含）。</p><p>实体：{{m.plan.filters.entity_ids?.length?`${m.plan.filters.entity_match==='all'?'同时匹配':'任一匹配'} ${m.plan.filters.entity_ids.length} 个实体`:'未限定实体'}}</p><p v-if="m.plan.entity_roles?.length">实体角色：{{m.plan.entity_roles.map(x=>x==='subject'?'主体':'产品').join('、')}}</p><p v-if="m.plan.requires_clarification">需要澄清：{{m.plan.clarification_candidates.map(x=>x.label).join('、')}}</p><p v-if="m.plan.free_text">未理解限制：{{m.plan.free_text}}</p><p v-if="m.plan.history_turns_considered !== undefined" class="meta">已参考历史 {{m.plan.history_turns_considered}} 轮，其中用户问题 {{m.plan.history_user_turns_used||0}} 轮。</p><p v-if="m.plan.filters.event_ids?.length" class="meta">附加事件：{{m.plan.filters.event_ids.length}} 个。</p><ul v-if="m.plan.event_targets?.length" class="meta"><li v-for="target in m.plan.event_targets" :key="target.event_id">附件 {{target.title_zh||target.event_id}}：{{target.status==='matched'?'已纳入':target.status==='filtered_out'?'不在当前范围，可移除附件或调整范围':'未找到，可移除附件'}}</li></ul><ul v-if="m.plan.warnings.length"><li v-for="w in m.plan.warnings" :key="w">{{w}}</li></ul></section><div v-for="c in m.citations" :key="m.id+'-'+c.index" class="evidence-item"><button :aria-expanded="expanded===m.id+':'+c.index" :aria-controls="'assistant-citation-'+m.id+'-'+c.index" @click="focusCitation(m.id,c.index)">[{{c.index}}] {{c.title}}</button><blockquote v-if="expanded===m.id+':'+c.index" :id="'assistant-citation-'+m.id+'-'+c.index" tabindex="-1">{{c.quote_text||'无段落摘录'}}<footer class="meta">段落 {{c.paragraph_id||'未提供'}}</footer></blockquote><a v-if="validUrl(c.source_url)" :href="preferredReadingUrl(c.source_url)" target="_blank" rel="noopener">{{ preferredReadingUrl(c.source_url) === c.source_url ? "打开来源" : "打开中文页面" }}</a><a v-if="validUrl(c.source_url) && preferredReadingUrl(c.source_url) !== c.source_url" :href="c.source_url" target="_blank" rel="noopener">查看采集原文（英文摘录核验）</a></div><p v-if="m.metrics" class="meta tabular turn-metrics"><span>完整匹配 <b>{{m.metrics.scope_total}}</b></span><span>取回 <b>{{m.metrics.retrieved_count}}</b></span><span>总结 <b>{{m.metrics.summarized_count}}</b></span><span>引用 <b>{{m.metrics.citation_count}}</b></span><span class="turn-coverage" :data-coverage="m.metrics.coverage">覆盖：{{m.metrics.coverage}}</span></p></details><button v-if="m.plan&&m.text==='规则解析预览'" @click="applyRulePlan(m.plan)">应用到总览</button></article></div><div class="assistant-round-spacer" :style="{height:roundSpacer+'px'}" aria-hidden="true"></div></div><button v-if="messages.length&&!atBottom" class="latest-message quiet-button" @click="scrollBottom">回到最新消息</button></div><p v-if="!messages.length" class="assistant-empty">输入问题开始研究；范围会随本轮记录。</p><div class="assistant-composer ask-question" data-testid="assistant-composer"><p v-if="attachment" class="assistant-attachment" data-testid="attached-event">下一问依据：{{attachment.title}} <button @click="attachment=undefined">移除</button> <button @click="openAttachment">查看事件</button></p><div class="composer-heading"><label for="assistant-question">问题</label><button class="quiet-button icon-button" :aria-pressed="previewDraft" :disabled="!draft" :title="previewDraft?'继续编辑':'预览'" :aria-label="previewDraft?'继续编辑':'预览'" @click="previewDraft=!previewDraft"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 5h16v14H4zM8 9h8M8 13h5"/></svg></button></div><MarkdownText v-if="previewDraft" class="draft-preview" :text="draft" /><textarea v-show="!previewDraft" id="assistant-question" v-model="draft" rows="3" placeholder="输入需要核查的问题" aria-describedby="composer-key-hint" @keydown="composerKey" /><p id="composer-key-hint" class="meta composer-key-hint">Enter 发送 · Ctrl+Enter 换行 · 支持 Markdown</p><p v-if="scopeIssue" class="error" role="alert">{{scopeIssue}}</p><div class="row"><button class="primary" :disabled="running||!draft.trim()||Boolean(scopeIssue)" @click="submit">发送</button><button :disabled="!draft.trim()" @click="planQuestion">按问题筛选</button><button v-if="running" @click="cancel">取消</button><button class="quiet-button icon-button" data-testid="history-toggle" :aria-expanded="historyOpen" title="历史会话" aria-label="历史会话" @click="toggleHistory"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 4v6h6M5 10a8 8 0 1 0 3-5"/></svg></button><button class="quiet-button icon-button" data-testid="new-conversation" title="新建会话" aria-label="新建会话" @click="create"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg></button></div><p class="meta" aria-live="polite">{{statusCopy(status)}}</p></div></section><aside v-if="historyOpen" class="history-panel" aria-label="研究会话历史" data-testid="history-panel" :style="{width:historyWidth+'px'}">
<div role="separator" tabindex="0" aria-orientation="vertical" :aria-valuenow="Math.round(historyWidth)" class="history-resizer" data-testid="history-resizer" aria-label="调整历史宽度（Alt 加方向键）" @pointerdown="resize($event,'history')" @keydown="keyResize($event,'history')"></div>
<div class="history-heading"><span>历史会话</span><button class="quiet-button" @click="historyOpen=false">{{compact?'返回对话':'收起'}}</button></div>
<div v-for="x in conversations" :key="x.id" class="history-row" :class="{active:x.id===activeId}">
<button class="history-title" data-testid="history-item" :data-conversation-id="x.id" :title="x.title" :aria-current="x.id===activeId?'true':undefined" @click="selectConversation(x.id); compact && (historyOpen=false)">{{x.title}}</button>
<button class="history-more icon-button quiet-button" data-testid="history-more" :aria-label="x.title+'的更多操作'" :aria-expanded="menuTarget===x.id" @click="showMenu($event,x.id)"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/></svg></button></div>
<p class="meta history-local-note">会话仅保存在此浏览器</p>
</aside></aside>
<Teleport to="body"><div v-if="menuTarget" class="conversation-menu" :style="menuPosition" aria-label="会话操作"><button @click="rename(menuTarget)">重命名</button><button @click="exportActive(menuTarget)">导出会话</button><button class="danger" @click="remove(menuTarget)">删除会话</button></div>
<dialog ref="renameDialog" class="conversation-rename" aria-labelledby="rename-title"><form @submit.prevent="saveName"><h2 id="rename-title">重命名会话</h2><label>会话名称<input ref="renameInput" v-model="renameTitle" maxlength="60" required /></label><div class="row"><button type="button" class="quiet-button" @click="renameDialog?.close()">取消</button><button class="primary" type="submit" :disabled="!renameTitle.trim()">保存</button></div></form></dialog></Teleport>
</template>
